SELECT bc.connection_id, bc.broker_id, bp.broker_code, bp.broker_name, bc.connection_status, bc.connected_at, bc.last_synced_at, COUNT(ia.connection_id) AS account_count FROM broker_connections bc JOIN broker_providers bp ON bp.broker_id = bc.broker_id LEFT JOIN investment_accounts ia ON ia.connection_id = bc.connection_id WHERE bc.connection_id IN
#{connectionId}
GROUP BY bc.connection_id, bc.broker_id, bp.broker_code, bp.broker_name, bc.connection_status, bc.connected_at, bc.last_synced_at

SELECT mock_profile_code
FROM broker_connections
WHERE connection_id = #{connectionId}

